package com.giftmarket.admin.service;import com.giftmarket.admin.dto.response.*;import com.giftmarket.admin.exception.AdminReturnException;import com.giftmarket.auth.exception.AuthenticationException;import com.giftmarket.global.storage.service.StorageService;import com.giftmarket.order.entity.*;import com.giftmarket.order.repository.*;import com.giftmarket.payment.entity.*;import com.giftmarket.payment.repository.*;import com.giftmarket.user.entity.*;import com.giftmarket.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class AdminReturnService{private static final Sort SORT=Sort.by(Sort.Order.desc("requestedAt"),Sort.Order.desc("id"));private final UserRepository users;private final ReturnRequestRepository returns;private final ReturnRequestItemRepository items;private final ReturnRequestImageRepository images;private final PaymentRepository payments;private final PaymentCancellationRepository refunds;private final StorageService storage;
@Transactional(readOnly=true)public AdminReturnPageResponse getReturns(Long adminId,int page,int size,String keyword,ReturnRequestStatus status,ReturnResponsibility responsibility){admin(adminId);var p=returns.findAdminReturns(norm(keyword),status,responsibility,PageRequest.of(page,size,SORT));var ids=p.stream().map(ReturnRequest::getId).toList();if(ids.isEmpty())return AdminReturnPageResponse.from(p,List.of());var sm=items.summarizeAdminReturns(ids).stream().collect(Collectors.toMap(AdminReturnItemSummaryProjection::getReturnId,Function.identity()));var pc=refunds.findAllByReturnRequestIdIn(ids).stream().collect(Collectors.toMap(x->x.getReturnRequest().getId(),Function.identity()));return AdminReturnPageResponse.from(p,p.stream().map(r->{var s=sm.get(r.getId());return AdminReturnSummaryResponse.from(r,s==null?null:s.getRepresentativeProductName(),s==null?0:s.getProductTypeCount(),s==null?0:s.getRequestedQuantity(),pc.get(r.getId()));}).toList());}
@Transactional(readOnly=true)public AdminReturnDetailResponse getReturn(Long adminId,Long id){admin(adminId);var r=returns.findAdminById(id).orElseThrow(()->new AdminReturnException("반품 요청을 찾을 수 없습니다."));var ris=items.findAdminByReturnRequestIdOrderByIdAsc(id);var evidence=images.findAllByReturnRequestIdOrderBySortOrderAsc(id).stream().map(i->new AdminReturnDetailResponse.Evidence(i.getId(),storage.createReadUrl(i.getObjectKey()),i.getSortOrder())).toList();var pc=refunds.findByReturnRequestId(id).orElse(null);var p=payments.findFirstByOrderIdOrderByIdDesc(r.getOrder().getId()).orElse(null);long refunded=p==null?0:refunds.sumAmountByPaymentIdAndStatus(p.getId(),PaymentCancellationStatus.SUCCEEDED);var o=r.getOrder();var u=o.getUser();var so=r.getSellerOrder();var s=so.getSeller();var sh=r.getCollectionShipment();return new AdminReturnDetailResponse(r.getId(),r.getStatus(),r.getReasonType(),r.getReason(),r.getResponsibility(),r.getRejectedReason(),r.getRequestedAt(),r.getApprovedAt(),r.getCollectingAt(),r.getReceivedAt(),r.getInspectedAt(),r.getRefundingAt(),r.getCompletedAt(),r.getRejectedAt(),r.getCanceledAt(),r.getFailedAt(),new AdminReturnDetailResponse.OrderInfo(o.getId(),o.getOrderNumber(),o.getStatus(),o.getOrderedAt()),new AdminReturnDetailResponse.Buyer(u.getId(),u.getName(),u.getEmail()),new AdminReturnDetailResponse.SellerInfo(so.getId(),so.getStatus(),s.getId(),s.getStoreName()),ris.stream().map(AdminReturnDetailResponse.Item::from).toList(),evidence,sh==null?null:new AdminReturnDetailResponse.CollectionInfo(sh.getId(),sh.getType(),sh.getStatus(),sh.getShippingCompany(),sh.getTrackingNumber(),sh.getShippedAt(),sh.getDeliveredAt()),new AdminReturnDetailResponse.RefundCalculation(r.getProductRefundAmount(),r.getOriginalShippingRefundAmount(),r.getReturnShippingCharge(),r.getRefundAmount()),p==null?null:new AdminReturnDetailResponse.PaymentInfo(p.getId(),p.getStatus(),p.getAmount(),refunded),AdminReturnDetailResponse.PaymentCancellationInfo.from(pc));}
private String norm(String v){return v==null||v.isBlank()?null:v.trim();}private void admin(Long id){if(id==null)throw new AuthenticationException("인증이 필요합니다.");var u=users.findById(id).orElseThrow(()->new AuthenticationException("사용자를 찾을 수 없습니다."));if(u.getRole()!=UserRole.ADMIN)throw new AuthenticationException("관리자 권한이 필요합니다.");}}
